head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getDataType]<br/>Body Column 정보를 사용하여 특정 Body Column 의 dataType 속성값을 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] Body 가 MultiLine(2줄) 구조인 그리드. 한 데이터 Row 가 2줄에 걸쳐 표시되며, Column 인덱스는 좌상단부터 우하단 순서로 0 부터 연속 고유값을 갖는다.\n  · 1줄 : col1(인덱스 0)=number / col2(인덱스 1)=float / col3(인덱스 2)=date\n  · 2줄 : col4(인덱스 3)=text / col5(인덱스 4)=date\n[절차] columnInfo(인덱스) 선택 후 getDataType 실행\n[확인] MultiLine 이어도 각 Column 이 고유 인덱스(0~4)로 조회되어 반환 dataType 이 해당 Column 의 dataType 과 일치하는지 확인"', '', 'label1');

    // MultiLine 검증용 5컬럼 DataList 생성 + 바인딩 (col1~col5)
    let strDl = '';
    strDl += '<w2:dataList ' + $c.gcm.strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="col1" name="name1" dataType="text"></w2:column>';
    strDl += '<w2:column id="col2" name="name2" dataType="text"></w2:column>';
    strDl += '<w2:column id="col3" name="name3" dataType="text"></w2:column>';
    strDl += '<w2:column id="col4" name="name4" dataType="text"></w2:column>';
    strDl += '<w2:column id="col5" name="name5" dataType="text"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '</w2:dataList>';
    $p.data.create(strDl);

    let arrDl = $p.data.getAllDataCollection("object");
    scwin.dlt_bind = arrDl[arrDl.length - 1];

    // 검증용 초기 데이터 설정
    dlt_bind.setJSON([
        { "col1": "12345", "col2": "67890", "col3": "20251225", "col4": "abc", "col5": "20260101" }
    ]);

    // MultiLine 그리드 생성 : gBody 에 2개의 row 를 두어 한 데이터 Row 가 2줄에 걸쳐 표시되게 한다.
    //  - 1줄 : col1 / col2 / col3 , 2줄 : col4 / col5
    //  - Body Column dataType : col1=number, col2=float, col3=date, col4=text, col5=date
    let grp_comp = $c.gcm.getTestGroup('');

    let strTarget = '';
    strTarget += '<w2:gridView ' + $c.gcm.strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:500px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a MultiLine grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol1" value="col1(idx0)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol2" value="col2(idx1)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol3" value="col3(idx2)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column colspan="2" width="150" style="" inputType="text" id="hcol4" value="col4(idx3)"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol5" value="col5(idx4)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col1" dataType="number" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col2" dataType="float" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col3" dataType="date" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    strTarget += '<w2:column colspan="2" width="150" style="" inputType="text" id="col4" dataType="text" value=""></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="col5" dataType="date" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



scwin.btn_getDataType_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());

    // 파라미터에 해당하는 Body Column 의 dataType 속성값 반환 (MultiLine 이어도 고유 인덱스로 조회)
    let dataType = target1.getDataType(columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue("getDataType(" + columnInfo + ") : " + dataType);
}
